// The laptop tasks announce every run by email to investors@. No email for
// several hours during the working day means Claude Code is not running --
// which looks identical to everything being fine, because the dashboard keeps
// updating from n8n regardless.
//
// This is not hypothetical: the chain died at 21:48 on 1 Oct and nobody knew
// until it restarted 84 hours later and said so itself. A Spintly call was
// missed and an AI Signal Labs meeting reached its day with no invite.
const QUIET_HOURS = 3;   // alert after this long with no run
const m = $input.first().json || {};
const ms = m.internalDate ? Number(m.internalDate) : null;

const hdrs = (m.payload && m.payload.headers) || [];
const subjHdr = hdrs.find((h) => String(h.name).toLowerCase() === 'subject');
const subject = subjHdr ? String(subjHdr.value) : '(unknown)';

const now = Date.now();
const ist = (t) => new Date(t + 330 * 60000).toISOString().replace('T', ' ').slice(0, 16) + ' IST';

// Only judge during the hours the tasks are supposed to run (09:00-22:00 IST).
const istHour = Number(new Date(now + 330 * 60000).toISOString().slice(11, 13));
const inHours = istHour >= 9 && istHour <= 22;

const hours = ms === null ? null : (now - ms) / 3600000;
const stale = inHours && (ms === null || hours > QUIET_HOURS);

return [{ json: {
  alert: stale,
  hours: hours === null ? null : Math.round(hours * 10) / 10,
  last_run_ist: ms === null ? 'no run found in the last 4 days' : ist(ms),
  last_subject: subject,
  checked_ist: ist(now),
  quiet_hours: QUIET_HOURS,
} }];

